void testMigrationsRunCleanly() {
  String url = "jdbc:h2:mem:test_" + UUID.randomUUID() + ";DB_CLOSE_DELAY=-1";
  Flyway f = Flyway.configure().dataSource(url, "sa", "").locations(...).load();
  MigrateResult r = f.migrate();
  if (!r.success) throw new AssertionError("migracje zawiodly");
}

